<script>
  /**
   * @component ContentList
   * A dynamic table of contents component that tracks and highlights the current heading
   * based on scroll position. Automatically builds a hierarchical structure from headings
   * in the document or a specified container.
   *
   * @param {string} [selector] - CSS selector for container to search for headings. If not provided, searches entire document
   * @param {string} [label] - Label text to display above the content list
   * @param {string} [class] - Additional CSS classes for the component wrapper
   * @param {string} [labelClass] - CSS classes for the label element
   * @param {string} [listClass] - CSS classes for the list element
   * @param {string} [liClass] - CSS classes for list item elements
   * @param {string} [aClass] - CSS classes for anchor elements
   * @param {string[]} [includes=['h2','h3','h4','h5','h6']] - Heading tags to include, replacing the default
   * @param {string[]} [excludes=[]] - CSS selectors to exclude from the list
   * @param {...*} [rest] - Additional props passed to the wrapper div
   *
   * @example
   * <ContentList
   *   label="On this page"
   *   selector=".content"
   *   includes={['h2', 'h3']}
   * />
   */
  import {
    findScrollContainer,
    rlh,
    scrollObserver,
  } from '@splendidlabz/utils/dom'
  import { onMount } from 'svelte'
  import NestedList from '../List/NestedList.svelte'
  import { buildStructure, updateAriaCurrent } from './contentlist.js'

  let {
    selector,
    label,
    class: klass = '',
    labelClass,
    listClass,
    liClass,
    aClass,
    options,
    includes: rawIncludes = [],
    excludes: rawExcludes = [],
    ...rest
  } = $props()

  const defaultOptions = {
    includes: ['h2', 'h3', 'h4', 'h5', 'h6'],
    excludes: ['.exclude-from-contentlist'],
  }

  let ref = $state(null)
  let elements = $state([])
  let structure = $state([])
  let currentHeading = $state(null)

  onMount(() => {
    if (typeof window === 'undefined') return
    const includes = rawIncludes.length ? rawIncludes : defaultOptions.includes
    const excludes = rawExcludes.concat(defaultOptions.excludes)
    const headingSelector = includes.join(',')
    const targetElement = selector ? document.querySelector(selector) : document

    collectHeadings()

    // Collects headings again when content with headings arrives late
    const observer = new MutationObserver(mutations => {
      const hasNewHeading = mutations.some(mutation =>
        Array.from(mutation.addedNodes).some(
          node =>
            node.nodeType === Node.ELEMENT_NODE &&
            (node.matches(headingSelector) ||
              node.querySelector(headingSelector)),
        ),
      )
      if (hasNewHeading) collectHeadings()
    })
    observer.observe(targetElement, { childList: true, subtree: true })

    return () => observer.disconnect()

    function collectHeadings() {
      elements = Array.from(
        targetElement.querySelectorAll(headingSelector),
      ).filter(el => {
        if (el.matches('.contentlist-exclude')) return false
        if (excludes.some(selector => el.matches(selector))) return false
        return true
      })

      structure = buildStructure(elements, liClass, aClass)
    }
  })

  $effect(_ => {
    if (!ref) return
    const scrollContainer = findScrollContainer(ref)

    const observer = scrollObserver(scrollContainer, {
      callback: data => {
        const { scrollTop } = data
        const offset = rlh() + 10 // 10px leeway for any rounding errors + some headroom

        const closestHeading = [...elements]
          .reverse()
          .find(h => h.offsetTop <= scrollTop + offset)
        // Update current heading and structure when closest heading changes
        if (closestHeading && closestHeading !== currentHeading) {
          currentHeading = closestHeading
          structure = updateAriaCurrent(structure, `#${closestHeading.id}`)
        }
      },
    })

    return () => observer.destroy()
  })
</script>

{#if structure.length}
  <div bind:this={ref} {...rest} class="contentlist {klass}">
    {#if typeof label === 'string'}
      <div class="label {labelClass}">{label}</div>
    {:else}
      {@render label?.()}
    {/if}
    <NestedList class={listClass} items={structure} />
  </div>
{/if}
